#include "stdafx.h"#include "MnemoWnd.h"#include "PipeClient.h"#include "FileNetWork.h"#include "Queue.h"#define CASE_INSENSITIVE_SEARCHCFileNetWork::CFileNetWork(void): m_nCountMax(0), m_nCount(0), m_arrData(NULL)  {  LoadFile();  }CFileNetWork::~CFileNetWork(void)  {  SaveFile();  ::BuffFree(m_arrData);  }void CFileNetWork::SaveFile()  {  if ( m_nCount == 0 ) return;  CharMP szPath;  lstrcpy( szPath, GetBasePath() );  lstrcat( szPath, "NetWork.save");  HFILE hFile = _lcreat( szPath, 0 );  if ( hFile != HFILE_ERROR )    {    for ( int n = 0; n < m_nCount; n++ )      m_arrData[n].dwCount = 0;    int nVersion = 0;    _hwrite( hFile, (char*)&nVersion, sizeof(nVersion) );    _hwrite( hFile, (char*)&m_nCount, sizeof(m_nCount) );    _hwrite( hFile, (char*)m_arrData, m_nCount*sizeof(SFileNetWork) );    _lclose( hFile );    }  }void CFileNetWork::LoadFile()  {  CharMP szPath;  lstrcpy( szPath, GetBasePath() );  lstrcat( szPath, "NetWork.save");  TakeOffReadOnly( szPath );  DWORD dwSize;  char * szBuffer = ::FileToBuff( szPath, dwSize );  if ( szBuffer )    {    int* nCount = (int*)szBuffer;    if ( nCount[0] == 0 )    if ( nCount[1]  > 0 )      {      int nSize = nCount[1]*sizeof(SFileNetWork);      char* buffer = (char*)::BuffAlloc( nSize, false );      if ( buffer != NULL )        {        memcpy( buffer, szBuffer + 2*sizeof( m_nCount ), nSize );        m_arrData = (SFileNetWork*)buffer;        m_nCount = nCount[1];        m_nCountMax = m_nCount;        }      }    ::BuffFree( szBuffer );    }  }bool CFileNetWork::AddItem( const char* pszFileName )  {  if ( m_nCount >= m_nCountMax )    {    int nSize = sizeof(SFileNetWork)*(m_nCount+10);    SFileNetWork* arrData = (SFileNetWork*)::BuffAlloc(nSize,true);    if ( arrData == NULL )      return false;    nSize = sizeof(SFileNetWork)*m_nCount;    if ( m_arrData != NULL )    memcpy( arrData, m_arrData, nSize );    //    m_nCountMax = (m_nCount+10);    ::BuffFree( m_arrData );    m_arrData = arrData;    //    }  lstrcpy( m_arrData[m_nCount++].name, pszFileName );  return true;  }int CFileNetWork::FindItem( const char* pszFileName ){#ifdef CASE_INSENSITIVE_SEARCH	char szFileName[_MAX_PATH] = { 0 };	strcpy_s (szFileName, _MAX_PATH, pszFileName);	CharLowerA (szFileName);	char szExt[_MAX_EXT];	_splitpath_s( szFileName, 0, 0, 0, 0, 0, 0, szExt, _MAX_EXT );	// Специфичные локальные файлы пропускаем	if ( lstrcmpi( szExt, ".save" ) == 0 )		return -1;	const char* pszName;	char szNameDir[_MAX_PATH] = { 0 };	strcpy_s (szNameDir, _MAX_PATH, GetBasePath());	if ( strstr( szFileName, "Dialogs_Pribors")!=NULL )	{		strcpy_s (szNameDir, _MAX_PATH, SYSTEM_PATH);		strcat_s (szNameDir, _MAX_PATH, "Dialogs_Pribors\\"); 	}	CharLowerA (szNameDir);	pszName = strstr( szFileName, szNameDir);	ASS( pszName != NULL )	if ( pszName == NULL )		return -1;	pszName += lstrlen(szNameDir);#else	std::string szNameDir=GetBasePath();	if ( strstr( pszFileName, "Dialogs_Pribors")!=NULL )	{		szNameDir=SYSTEM_PATH;		szNameDir+="Dialogs_Pribors\\";	}	pszName = strstr( pszFileName,  szNameDir.c_str());	ASS( pszName != NULL )	if ( pszName == NULL ) return -1;	pszName += szNameDir.length();#endif // CASE_INSENSITIVE_SEARCH	for ( int n = 0; n < m_nCount; n++ )		if ( lstrcmpi( pszName, m_arrData[n].name ) == 0 )			return n;  //	if ( AddItem( pszName ) )		return m_nCount-1;	return -1;}////////////////////////////////////////////////////////////////////////////////////////// Проверяет и, если понадобится, создает директорию.//BOOL IsCreateDir(LPCTSTR pszDir)  {  DWORD  dwFileAttr = GetFileAttributes(pszDir);  if ( dwFileAttr &  FILE_ATTRIBUTE_DIRECTORY  &&   dwFileAttr != 0xFFFFFFFF)  return TRUE;  return CreateDirectory(pszDir,NULL);  }////////////////////////////////////////////////////////////////////////////////////////// Рекурсивное создание директорий.//void CreateDir(char* szDir,int j)  {  if ( IsCreateDir(szDir) )  return;  //  char* ptr = szDir;  while ( *ptr )    {    if ( *ptr == '/' ) *ptr = '\\';    ptr++;    }  //  CharMP szBuff;  do    {    lstrcpy(szBuff,szDir);    LPTSTR pszDir = szBuff+j;    pszDir = strchr(pszDir,'\\');    if ( pszDir ) pszDir++;    else break;    j = int(pszDir-szBuff);	  *pszDir = '\0';    }  while ( IsCreateDir(szBuff) );  } void NetworkFile( const char* pszFileName )  {  if ( !CPipeClient::ms_bCopyNetworkFile )    return;  //  if ( lstrcmp(CPipeClient::ms_szServer,".") == 0 ) return;  //  CPipeClient* pipe = CPipeClient::ms_pMainPipe;  if ( pipe == NULL ) return;  //  static CFileNetWork file;  int n = file.FindItem( pszFileName );  if ( n < 0 ) return;  file.m_arrData[n].dwCount++;  if ( file.m_arrData[n].dwCount > 1 ) return;  UINT     size = 0;  FILETIME time = file.m_arrData[n].time;  char* name = file.m_arrData[n].name;  char* ptr = pipe->GetFile( name, time, size );  if ( ptr == 0 ) return;  FILETIME* W = (FILETIME*)ptr;  file.m_arrData[n].time = *W;//time;  //  CharMP szPath,szDir;  _splitpath_s( name, 0, 0, szDir, _MAX_DIR, 0, 0, 0, 0 );  //  char* pBase = GetBasePath();  lstrcpy( szPath, pBase );  lstrcat( szPath, szDir );  //    CreateDir( szPath, lstrlen(pBase) );  //  lstrcpy( szPath, pBase );  lstrcat( szPath, name );  //  TakeOffReadOnly( szPath );  bool bReturn = false;  HFILE hFile = _lcreat( szPath, 0 );  if ( hFile != HFILE_ERROR )    {    _hwrite( hFile, ptr+sizeof(time), size-sizeof(time) );    _lclose( hFile );    }  delete [] ptr;  }